import AVFoundation
import CoreHaptics
import UIKit
import HearthsideCore

/// Soft card sounds. Files live in Resources/sounds (generated by Tools/make_sounds.py,
/// CC0 — see docs/licenses). Uses the ambient category so the player's music keeps playing.
@MainActor
final class SoundService {
    enum Effect: String, CaseIterable {
        case place = "card_place"
        case flip = "card_flip"
        case foundation = "card_foundation"
        case shuffle = "shuffle"
        case win = "win"
        case warmth = "warmth"
    }

    var isEnabled = true
    private var players: [Effect: [AVAudioPlayer]] = [:]
    private var nextIndex: [Effect: Int] = [:]

    init() {
        try? AVAudioSession.sharedInstance().setCategory(.ambient, options: [.mixWithOthers])
        for effect in Effect.allCases {
            guard let url = Bundle.main.url(forResource: effect.rawValue, withExtension: "wav", subdirectory: "sounds")
                    ?? Bundle.main.url(forResource: effect.rawValue, withExtension: "wav") else { continue }
            // A few players per effect so quick taps can overlap.
            players[effect] = (0..<3).compactMap { _ in
                let player = try? AVAudioPlayer(contentsOf: url)
                player?.volume = effect == .win ? 0.7 : 0.5
                player?.prepareToPlay()
                return player
            }
        }
    }

    func play(_ effect: Effect) {
        guard isEnabled, let pool = players[effect], !pool.isEmpty else { return }
        let index = nextIndex[effect, default: 0]
        nextIndex[effect] = (index + 1) % pool.count
        let player = pool[index]
        player.currentTime = 0
        player.play()
    }
}

/// Core Haptics for card drops (a soft "tock"), with UIKit generators as fallback.
@MainActor
final class HapticsService {
    var isEnabled = true
    private var engine: CHHapticEngine?
    private let soft = UIImpactFeedbackGenerator(style: .soft)
    private let notification = UINotificationFeedbackGenerator()

    init() {
        guard CHHapticEngine.capabilitiesForHardware().supportsHaptics else { return }
        engine = try? CHHapticEngine()
        engine?.isAutoShutdownEnabled = true
        engine?.resetHandler = { [weak self] in
            guard let service = self else { return }
            Task { @MainActor in try? service.engine?.start() }
        }
        try? engine?.start()
    }

    func cardPlaced(strong: Bool) {
        guard isEnabled else { return }
        guard let engine else {
            soft.impactOccurred(intensity: strong ? 0.9 : 0.6)
            return
        }
        let event = CHHapticEvent(eventType: .hapticTransient, parameters: [
            CHHapticEventParameter(parameterID: .hapticIntensity, value: strong ? 0.8 : 0.5),
            CHHapticEventParameter(parameterID: .hapticSharpness, value: strong ? 0.35 : 0.2)
        ], relativeTime: 0)
        do {
            try engine.start()
            let player = try engine.makePlayer(with: CHHapticPattern(events: [event], parameters: []))
            try player.start(atTime: CHHapticTimeImmediate)
        } catch {
            soft.impactOccurred()
        }
    }

    func success() {
        guard isEnabled else { return }
        notification.notificationOccurred(.success)
    }

    func denied() {
        guard isEnabled else { return }
        soft.impactOccurred(intensity: 0.3)
    }
}

/// Loads the solver-verified deal pools shipped in Resources/deals.
enum DealLibraryLoader {
    static func loadAll(bundle: Bundle = .main) -> [Int: DealLibrary] {
        var result: [Int: DealLibrary] = [:]
        for draw in [1, 3] {
            let name = "klondike-draw\(draw)"
            guard let url = bundle.url(forResource: name, withExtension: "json", subdirectory: "deals")
                    ?? bundle.url(forResource: name, withExtension: "json"),
                  let data = try? Data(contentsOf: url),
                  let library = try? DealLibrary.load(from: data) else { continue }
            result[draw] = library
        }
        return result
    }
}
